BEGIN;
-- ===== Subject 1: Agriculture & Environmental Sciences
DELETE FROM subject_sections WHERE subject_id=(SELECT id FROM subjects WHERE display_order=1 AND status='published');
UPDATE subjects SET about_title='About Agriculture & Environmental Sciences', about_body='<p>Agriculture and Environmental Sciences covers how we grow food, manage land and water, protect wildlife and respond to climate change. The field mixes biology, chemistry, data and economics with hands-on fieldwork, labs and policy.</p><p>Abroad, you can study at universities with working farms, research stations, marine labs and forests, and learn from regions that lead in agri-tech, sustainable farming and conservation.</p><p>Popular specializations include Agribusiness, Food Science, Environmental Science, Marine Biology, Renewable Energy and Forestry.</p>', why_title='Why study Agriculture & Environmental Sciences?', why_body='<p><strong>Demand is growing.</strong> Food security, net-zero targets and biodiversity loss are pushing governments and companies to hire graduates who understand land, water and climate.</p><p><strong>Practical, outdoors learning.</strong> Many programmes include field trips, placements and lab work, not just lectures.</p><p><strong>Global career options.</strong> Graduates work in farming, food, environmental consulting, conservation, energy and international development.</p><p><strong>Strong study destinations.</strong> The Netherlands, Australia, the UK, the US and Canada all have well-regarded agriculture and environment schools.</p>' WHERE id=(SELECT id FROM subjects WHERE display_order=1 AND status='published');
UPDATE subject_study_levels SET about_title='About Foundation in Agriculture & Environmental Sciences', about_body='<p>A Foundation in Agriculture &amp; Environmental Sciences. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Usually for students who have finished secondary school but don''t yet meet direct-entry requirements for a bachelor''s.</p>', why_title='Why choose a Foundation in Agriculture & Environmental Sciences?', why_body='<p>Foundation study in Agriculture &amp; Environmental Sciences lets you build the skills and credentials employers in this field look for. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=1 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='foundation');
UPDATE subject_study_levels SET about_title='About Pathway in Agriculture & Environmental Sciences', about_body='<p>A Pathway in Agriculture &amp; Environmental Sciences. A programme run with a partner university that leads into the first or second year of a degree.</p><p>Usually for students who need extra academic or English preparation, or want guaranteed progression to a partner university.</p>', why_title='Why choose a Pathway in Agriculture & Environmental Sciences?', why_body='<p>Pathway study in Agriculture &amp; Environmental Sciences lets you build the skills and credentials employers in this field look for. A programme run with a partner university that leads into the first or second year of a degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=1 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='pathway');
UPDATE subject_study_levels SET about_title='About Diploma in Agriculture & Environmental Sciences', about_body='<p>A Diploma in Agriculture &amp; Environmental Sciences. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Usually for students who want job-focused training or a flexible route into a degree.</p>', why_title='Why choose a Diploma in Agriculture & Environmental Sciences?', why_body='<p>Diploma study in Agriculture &amp; Environmental Sciences lets you build the skills and credentials employers in this field look for. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=1 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='diploma');
UPDATE subject_study_levels SET about_title='About Bachelor''s in Agriculture & Environmental Sciences', about_body='<p>A Bachelor''s in Agriculture &amp; Environmental Sciences. Your first university degree, typically 3–4 years.</p><p>Usually requires completed secondary school with strong results, plus English proof (for example IELTS or TOEFL).</p>', why_title='Why choose a Bachelor''s in Agriculture & Environmental Sciences?', why_body='<p>Bachelor''s study in Agriculture &amp; Environmental Sciences lets you build the skills and credentials employers in this field look for. Your first university degree, typically 3–4 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=1 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='bachelors');
UPDATE subject_study_levels SET about_title='About Master''s in Agriculture & Environmental Sciences', about_body='<p>A Master''s in Agriculture &amp; Environmental Sciences. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Usually requires a bachelor''s degree with good grades, English proof, and sometimes work experience or tests such as GRE or GMAT.</p>', why_title='Why choose a Master''s in Agriculture & Environmental Sciences?', why_body='<p>Master''s study in Agriculture &amp; Environmental Sciences lets you build the skills and credentials employers in this field look for. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=1 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='masters');
UPDATE subject_study_levels SET about_title='About MBA in Agriculture & Environmental Sciences', about_body='<p>A MBA in Agriculture &amp; Environmental Sciences. A master''s in business and management, usually for people with work experience.</p><p>Usually requires a bachelor''s degree, 2–5 years of work experience, GMAT/GRE (some schools waive) and English proof.</p>', why_title='Why choose a MBA in Agriculture & Environmental Sciences?', why_body='<p>MBA study in Agriculture &amp; Environmental Sciences lets you build the skills and credentials employers in this field look for. A master''s in business and management, usually for people with work experience.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=1 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='mba');
UPDATE subject_study_levels SET about_title='About PhD in Agriculture & Environmental Sciences', about_body='<p>A PhD in Agriculture &amp; Environmental Sciences. Original research under a supervisor, typically 3–5 years.</p><p>Usually requires a master''s degree (or an exceptional bachelor''s), a research proposal and supervisor agreement.</p>', why_title='Why choose a PhD in Agriculture & Environmental Sciences?', why_body='<p>PhD study in Agriculture &amp; Environmental Sciences lets you build the skills and credentials employers in this field look for. Original research under a supervisor, typically 3–5 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=1 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='phd');
-- ===== Subject 2: Architecture & Built Environment
DELETE FROM subject_sections WHERE subject_id=(SELECT id FROM subjects WHERE display_order=2 AND status='published');
UPDATE subjects SET about_title='About Architecture & Built Environment', about_body='<p>Architecture and the Built Environment covers how buildings, cities and infrastructure are designed, planned, costed, built and managed. It combines creative design with engineering, law, economics and sustainability.</p><p>Programmes range from architecture and interior design to urban planning, surveying, construction management and real estate.</p><p>Studying abroad exposes you to different building codes, climates and design cultures, and to professional accreditation routes such as RIBA/ARB in the UK and NCARB in the US.</p>', why_title='Why study Architecture & Built Environment?', why_body='<p><strong>Every country needs buildings and infrastructure.</strong> Housing shortages, urban growth and retrofit for net-zero keep demand for skilled professionals high.</p><p><strong>Creative and technical.</strong> You work with design software, BIM, models and real sites, often on studio projects that build a portfolio.</p><p><strong>Professional pathways.</strong> Many degrees are accredited by bodies such as RIBA, RICS and CIOB, which helps with registration and chartership.</p><p><strong>Wide career range.</strong> Graduates become architects, planners, surveyors, project managers, developers and sustainability consultants.</p>' WHERE id=(SELECT id FROM subjects WHERE display_order=2 AND status='published');
