-- ===== Subject 4: Business & Management
DELETE FROM subject_sections WHERE subject_id=(SELECT id FROM subjects WHERE display_order=4 AND status='published');
UPDATE subjects SET about_title='About Business & Management', about_body='<p>Business and Management covers how organisations are run: accounting, finance, marketing, operations, supply chain, human resources, strategy, entrepreneurship and leadership.</p><p>Degrees range from general business administration to specialist routes such as fintech, business analytics, luxury management and hospitality.</p><p>Studying abroad gives access to international classmates, employer networks and, at some schools, internationally recognised accreditation such as AACSB, AMBA or EQUIS.</p>', why_title='Why study Business & Management?', why_body='<p><strong>Versatile degree.</strong> Business skills apply in almost every sector, from banking and tech to healthcare and non-profits.</p><p><strong>International networks.</strong> Business schools abroad attract diverse cohorts and employers recruiting globally.</p><p><strong>Clear progression.</strong> Bachelor''s, master''s and MBA routes let you build skills and move into management.</p><p><strong>Professional qualifications.</strong> Many courses give exemptions toward ACCA, CIMA, CFA or CIPD.</p>' WHERE id=(SELECT id FROM subjects WHERE display_order=4 AND status='published');
