INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=1 AND status='published'),'about','About Marine Biology',NULL,'<p>Marine Biology focuses on life in the oceans and coastal ecosystems. It sits within Agriculture &amp; Environmental Sciences and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=1 AND status='published') AND name='Marine Biology'));
