INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=2 AND status='published'),'destination','Canada',NULL,'<p>Growing demand for housing and infrastructure professionals.</p><p>Post-Graduation Work Permit of up to 3 years for eligible programmes (degree graduates are exempt from the field-of-study list). Study permits are capped nationally (408,000 for 2026), but master''s and doctoral students at public institutions are exempt from the cap from 1 January 2026.</p>','published',4,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=2 AND status='published') AND name='Architecture'));
