INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=2 AND status='published'),'destination','Australia',NULL,'<p>Strong industry links, with courses accredited by Australian professional bodies.</p><p>Student visa fee is AUD 2,500 from 1 July 2026 and the national planning level is 295,000 new international students (kept for 2027). Graduates can apply for the Temporary Graduate visa (485); length depends on qualification and region.</p>','published',3,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=2 AND status='published') AND name='Civil Infrastructure'));
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=2 AND status='published'),'destination','Canada',NULL,'<p>Growing demand for housing and infrastructure professionals.</p><p>Post-Graduation Work Permit of up to 3 years for eligible programmes (degree graduates are exempt from the field-of-study list). Study permits are capped nationally (408,000 for 2026), but master''s and doctoral students at public institutions are exempt from the cap from 1 January 2026.</p>','published',4,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=2 AND status='published') AND name='Civil Infrastructure'));
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=2 AND status='published'),'destination','Netherlands',NULL,'<p>Renowned for innovative architecture and urbanism (for example TU Delft).</p><p>Many English-taught programmes. Graduates can use the Orientation Year visa to look for work for up to 12 months.</p>','published',5,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=2 AND status='published') AND name='Civil Infrastructure'));
