INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=2 AND status='published'),'about','About Construction Technology',NULL,'<p>Construction Technology focuses on modern methods, materials and digital tools in construction. It sits within Architecture &amp; Built Environment and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=2 AND status='published') AND name='Construction Technology'));
