INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=4 AND status='published'),'about','About Accounting',NULL,'<p>Accounting focuses on recording, analysing and reporting financial information. It sits within Business &amp; Management and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=4 AND status='published') AND name='Accounting'));
