INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=4 AND status='published'),'about','About Real Estate Management',NULL,'<p>Real Estate Management focuses on managing property portfolios and investments. It sits within Business &amp; Management and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=4 AND status='published') AND name='Real Estate Management'));
