INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,study_level_id) SELECT gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=5 AND status='published'),'destination','Germany',NULL,'<p>Low or no tuition at most public universities and strong engineering and software industries.</p><p>Most public universities charge little or no tuition (Baden-Württemberg charges non-EU students about €1,500 per semester), but you need to show living-cost funds. Graduates can stay up to 18 months to look for work in their field.</p>','published',4,(SELECT id FROM study_levels WHERE slug='foundation') WHERE EXISTS (SELECT 1 FROM subject_study_levels x WHERE x.subject_id=(SELECT id FROM subjects WHERE display_order=5 AND status='published') AND x.study_level_id=(SELECT id FROM study_levels WHERE slug='foundation'));
