INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=5 AND status='published'),'destination','United States',NULL,'<p>Most of the world''s leading tech employers and top research universities.</p><p>Graduates can work on OPT for 12 months, with a 24-month STEM extension for eligible degrees. Visa and work-fee rules (OPT and H-1B) are under active review, so check USCIS before planning. International tuition is commonly $25,000–$65,000 a year.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=5 AND status='published') AND name='Cyber Security'));
