INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=5 AND status='published'),'destination','Germany',NULL,'<p>Low or no tuition at most public universities and strong engineering and software industries.</p><p>Most public universities charge little or no tuition (Baden-Württemberg charges non-EU students about €1,500 per semester), but you need to show living-cost funds. Graduates can stay up to 18 months to look for work in their field.</p>','published',4,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=5 AND status='published') AND name='Computer Animation'));
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=5 AND status='published'),'destination','Ireland',NULL,'<p>European headquarters of many global tech companies.</p><p>English-speaking, with a major European tech and finance base. The Stay Back scheme allows graduates to remain to seek work (up to 12 months after a bachelor''s, 24 months after a master''s or PhD).</p>','published',5,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=5 AND status='published') AND name='Computer Animation'));
